-- Audyt sprzątania (2026-10-23): funkcje public — liczba przeciążeń,
-- triggery w całej bazie (także auth.users) i wywołania (gdy track_functions).
SELECT n.ord::int AS ord,
       (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = n.name) AS wersje,
       (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid
         WHERE p.pronamespace = 'public'::regnamespace AND p.proname = n.name AND NOT t.tgisinternal) AS triggery,
       (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid JOIN pg_class c ON c.oid = t.tgrelid
         WHERE p.pronamespace = 'public'::regnamespace AND p.proname = n.name AND c.relnamespace <> 'public'::regnamespace) AS triggery_poza_public,
       (SELECT sum(f.calls) FROM pg_stat_user_functions f WHERE f.schemaname = 'public' AND f.funcname = n.name) AS wywolania
